use base64::engine::general_purpose::STANDARD;
use base64::Engine as _;
use chat::GroupDocState;
use hyperware_crdt::CommitteeDoc;

#[test]
fn decode_membership_acl_snapshot_payload() {
    let payload = "";

    let update_bytes = STANDARD.decode(payload).expect("base64 decode");
    assert_eq!(update_bytes.len(), 2648);

    let mut doc = CommitteeDoc::<GroupDocState>::empty(
        "chat:group:group:fake.os:1764248720:4164775213".to_string(),
    )
    .expect("doc init");
    doc.apply_update(&update_bytes).expect("apply update");

    let state = doc.read_state().expect("state");
    let member_count = state.group.members.len();
    let role_count = state.group.roles.len();
    let sub_count = state.group.subscribers.entries.len();
    assert!(
        member_count > 0,
        "members empty (roles={}, subs={})",
        role_count,
        sub_count
    );
}
